const CAP=(x,y,v=1)=>v?`<rect x="${x-5}" y="${y-18}" width="10" height="36" fill="var(--panel)"/><line x1="${x-5}" y1="${y-16}" x2="${x-5}" y2="${y+16}" stroke="var(--accent)" stroke-width="3.5"/><line x1="${x+5}" y1="${y-16}" x2="${x+5}" y2="${y+16}" stroke="var(--accent)" stroke-width="3.5"/>`:`<rect x="${x-18}" y="${y-5}" width="36" height="10" fill="var(--panel)"/><line x1="${x-16}" y1="${y-5}" x2="${x+16}" y2="${y-5}" stroke="var(--accent)" stroke-width="3.5"/><line x1="${x-16}" y1="${y+5}" x2="${x+16}" y2="${y+5}" stroke="var(--accent)" stroke-width="3.5"/>`;
const GND=(x,y)=>`<line x1="${x}" y1="${y}" x2="${x}" y2="${y+14}" stroke="var(--ink)" stroke-width="2"/><line x1="${x-12}" y1="${y+14}" x2="${x+12}" y2="${y+14}" stroke="var(--ink)" stroke-width="2"/><line x1="${x-7}" y1="${y+19}" x2="${x+7}" y2="${y+19}" stroke="var(--ink)" stroke-width="2"/><line x1="${x-3}" y1="${y+24}" x2="${x+3}" y2="${y+24}" stroke="var(--ink)" stroke-width="2"/>`;
